// useScrollScene — the scroll story's liquid-weight spine.
//
// A rAF-coalesced read of the story's own scroll port, fed through keyframes.js's
// `SmoothProgress`, so the damped 0..1 LAGS the finger and settles after it lifts. The
// library's scroll registers are 1:1 with the scroll by construction (the `scroll()`
// recipe, `useScrollTrigger`'s progress); the weight is this page's own register, so it
// lives beside the one story that mounts it.
//
// No perpetual rAF: `SmoothProgress.play()` ticks only while unsettled and parks at rest,
// and the port holds at most one frame in flight per scroll burst.
import { SmoothProgress } from "@mkbabb/keyframes.js";
import {
    onMounted,
    onScopeDispose,
    readonly,
    ref,
    toValue,
    watch,
    type MaybeRefOrGetter,
    type Ref,
} from "vue";
import { useReducedMotion } from "@glass/composables/motion/motion-core";

export interface UseScrollSceneOptions {
    /** The story's own scroll port (passed explicitly, never auto-discovered). */
    source: MaybeRefOrGetter<HTMLElement | null>;
    /** The element the damped value is written onto as a custom property. */
    bindEl: MaybeRefOrGetter<HTMLElement | null>;
    /** The custom property the damped 0..1 is written to (`--scene-t`). */
    property: string;
    /** The liquid-weight scrub in [0, 1]: 0 snaps 1:1, 1 drifts heaviest. Reduced motion snaps. */
    scrub: number;
}

export interface UseScrollSceneReturn {
    /** The damped 0..1 progress. */
    progress: Readonly<Ref<number>>;
    /** Detach the port and stop the smoother. */
    dispose: () => void;
}

const clamp01 = (v: number): number => (v < 0 ? 0 : v > 1 ? 1 : v);

/**
 * The scrub → damping map. `SmoothProgress.damping` is "higher = less lag", the inverse
 * of scrub, so damping = 1 − scrub·(1 − FLOOR): scrub 0 catches up at once, scrub 1 drifts
 * at the floor, which still converges (a damping of 0 stalls).
 */
function scrubToDamping(scrub: number): number {
    const FLOOR = 0.08;
    return 1 - clamp01(scrub) * (1 - FLOOR);
}

export function useScrollScene(options: UseScrollSceneOptions): UseScrollSceneReturn {
    const reduced = useReducedMotion();
    const progress = ref(0);
    const smoother = new SmoothProgress({
        damping: scrubToDamping(options.scrub),
        initial: 0,
        clamp: true,
        respectReducedMotion: false,
    });

    function emit(value: number): void {
        const v = clamp01(value);
        progress.value = v;
        toValue(options.bindEl)?.style.setProperty(options.property, String(v));
    }
    smoother.play(emit);

    let port: HTMLElement | null = null;
    let frame = 0;

    function sample(): void {
        frame = 0;
        if (!port) return;
        const extent = port.scrollHeight - port.clientHeight;
        const raw = extent > 0 ? clamp01(port.scrollTop / extent) : 0;
        smoother.setTarget(raw);
        // Reduced motion: a 1:1 snap, no interpolated drift.
        if (reduced.value) {
            smoother.snap();
            emit(raw);
        }
    }
    const schedule = (): void => {
        if (!frame) frame = requestAnimationFrame(sample);
    };

    onMounted(() => {
        port = toValue(options.source);
        port?.addEventListener("scroll", schedule, { passive: true });
        schedule();
    });
    const stopReducedWatch = watch(reduced, (next) => {
        if (next) schedule();
    });

    function dispose(): void {
        port?.removeEventListener("scroll", schedule);
        port = null;
        if (frame) cancelAnimationFrame(frame);
        frame = 0;
        smoother.stop();
        stopReducedWatch();
    }
    onScopeDispose(dispose);

    return { progress: readonly(progress), dispose };
}

